import inspect

import torch
from flask import Flask, jsonify, request
from transformers import AutoModelForSequenceClassification, AutoTokenizer

MODEL_DIR = "/app/model_cache/sentiment_model"

tokenizer = AutoTokenizer.from_pretrained(MODEL_DIR)
model = AutoModelForSequenceClassification.from_pretrained(MODEL_DIR)
model.eval()

# Map model label ids -> canonical names, tolerant of label naming variations.
_id2label = getattr(model.config, "id2label", None) or {0: "NEGATIVE", 1: "POSITIVE"}


def _canonical(label):
    text = str(label).lower()
    if "pos" in text or text in ("label_1", "1"):
        return "positive"
    if "neg" in text or text in ("label_0", "0"):
        return "negative"
    return None


app = Flask(__name__)


def _predict(text):
    kwargs = {"return_tensors": "pt"}
    params = inspect.signature(tokenizer.__call__).parameters
    if "truncation" in params or any(
        p.kind == inspect.Parameter.VAR_KEYWORD for p in params.values()
    ):
        kwargs["truncation"] = True
        kwargs["max_length"] = int(getattr(tokenizer, "model_max_length", 512) or 512)
        if kwargs["max_length"] > 512:
            kwargs["max_length"] = 512
    try:
        inputs = tokenizer(text, **kwargs)
    except TypeError:
        inputs = tokenizer(text, return_tensors="pt")
    with torch.no_grad():
        logits = model(**inputs).logits
    probs = torch.softmax(logits, dim=-1)[0].tolist()

    scores = {"positive": 0.0, "negative": 0.0}
    for idx, prob in enumerate(probs):
        name = _canonical(_id2label.get(idx, _id2label.get(str(idx), idx)))
        if name is None:
            name = "positive" if idx == 1 else "negative"
        scores[name] = float(prob)
    sentiment = "positive" if scores["positive"] >= scores["negative"] else "negative"
    return sentiment, scores


@app.route("/sentiment", methods=["POST"])
def sentiment():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify({"error": "Request body must be JSON with a 'text' field"}), 400
    if "text" not in data:
        return jsonify({"error": "Missing required field: 'text'"}), 400
    text = data["text"]
    if not isinstance(text, str) or not text.strip():
        return jsonify({"error": "Field 'text' must be a non-empty string"}), 400

    try:
        label, scores = _predict(text)
    except Exception as exc:  # noqa: BLE001
        return jsonify({"error": f"Inference failed: {exc}"}), 400

    return jsonify({"sentiment": label, "confidence": scores})


@app.route("/health", methods=["GET"])
def health():
    return jsonify({"status": "ok"})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, threaded=True)

